+// Notes MCP server: in-memory note store exposed via two tools.
+
+// In-memory storage keyed by stable generated note id.
+const notes = new Map();
+let counter = 0;
+
+function nextId() {
+  counter += 1;
+  return `n${counter}`;
+}
+
+function isNonEmptyString(value) {
+  return typeof value === 'string' && value.trim().length > 0;
+}
+
+const TOOLS = [
+  {
+    name: 'note_create',
+    description:
+      'Create a new note with a required non-empty title and body. ' +
+      'Stores the note in memory and returns its stable generated id.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        title: { type: 'string', description: 'Non-empty title of the note.' },
+        body: { type: 'string', description: 'Non-empty body content of the note.' }
+      },
+      required: ['title', 'body'],
+      additionalProperties: false
+    },
+    annotations: {
+      readOnlyHint: false,
+      destructiveHint: false,
+      idempotentHint: false,
+      openWorldHint: false
+    }
+  },
+  {
+    name: 'note_get',
+    description: 'Retrieve a stored note by its required note_id.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        note_id: { type: 'string', description: 'The id of the note to retrieve.' }
+      },
+      required: ['note_id'],
+      additionalProperties: false
+    },
+    annotations: {
+      readOnlyHint: true,
+      destructiveHint: false,
+      idempotentHint: true,
+      openWorldHint: false
+    }
+  }
+];
+
+export async function listTools() {
+  return TOOLS;
+}
+
+export async function callTool(name, args) {
+  const input = args || {};
+
+  if (name === 'note_create') {
+    const { title, body } = input;
+    if (!isNonEmptyString(title)) {
+      throw new Error('title is required and must be a non-empty string');
+    }
+    if (!isNonEmptyString(body)) {
+      throw new Error('body is required and must be a non-empty string');
+    }
+    const id = nextId();
+    const note = { id, title, body };
+    notes.set(id, note);
+    const text = `Note created\nid: ${id}\ntitle: ${title}\nbody: ${body}`;
+    return { content: [{ type: 'text', text }] };
+  }
+
+  if (name === 'note_get') {
+    const { note_id } = input;
+    if (!isNonEmptyString(note_id)) {
+      throw new Error('note_id is required and must be a non-empty string');
+    }
+    const note = notes.get(note_id);
+    if (!note) {
+      throw new Error(`note not found for note_id: ${note_id}`);
+    }
+    const text = `Note\nid: ${note.id}\ntitle: ${note.title}\nbody: ${note.body}`;
+    return { content: [{ type: 'text', text }] };
+  }
+
+  throw new Error(`unknown tool: ${name}`);
+}
